package kr.co.TRSolution.trsIbp.notice.service.impl;import java.util.*;import javax.annotation.Resource;import org.springframework.stereotype.Service;import kr.co.TRSolution.trsIbp.notice.mapper.NoticeMapper;import kr.co.TRSolution.trsIbp.notice.service.NoticeService;import kr.co.TRSolution.trsIbp.notice.vo.NoticeVO;@Service("noticeService")public class NoticeServiceImpl implements NoticeService{@Resource(name="noticeMapper")private NoticeMapper m;public List<NoticeVO> selectNoticeList(NoticeVO v){return m.selectNoticeList(v);}public List<NoticeVO> selectPopupList(NoticeVO v){return m.selectPopupList(v);}public NoticeVO selectNotice(NoticeVO v){return m.selectNotice(v);}public int saveNotice(NoticeVO v){if(v.getNoticeTitle()==null||v.getNoticeTitle().trim().isEmpty())throw new IllegalArgumentException("제목을 입력해 주세요.");if(v.getNoticeCn()==null||v.getNoticeCn().trim().isEmpty())throw new IllegalArgumentException("내용을 입력해 주세요.");return v.getNoticeSn()==null?m.insertNotice(v):m.updateNotice(v);}public int deleteNotice(NoticeVO v){return m.deleteNotice(v);}}
